"""动作执行 — 还原自 src/agents/interaction/actions.py。

真 catalog（config/actions/<robot>.yaml）+ 真 .npy 库 + MockAdapter（解密原文）。
动作经 motion lease 仲裁后交给 adapter 播放。
"""
from __future__ import annotations

import asyncio
import inspect
from typing import Any

import yaml

from src.hardware.robot_profile import load_robot_profile
from src.hardware.mock_adapter import MockAdapter
from src.logger import get_logger
from src.runtime.motion_arbitration import release_lease, request_interaction_action_lease
from src.runtime.robot_mode import RobotMode, set_mode

log = get_logger("Action")

_adapter = None
_actions: dict[str, dict] | None = None


def get_adapter():
    global _adapter
    if _adapter is None:
        prof = load_robot_profile()
        try:
            sig = inspect.signature(MockAdapter.__init__)
            kw: dict[str, Any] = {}
            if "action_rag_path" in sig.parameters:
                kw["action_rag_path"] = prof.actions.library_path
            if "playback_dt_s" in sig.parameters:
                kw["playback_dt_s"] = prof.actions.playback_dt_s
            _adapter = MockAdapter(**kw)
        except Exception:
            _adapter = MockAdapter()
    return _adapter


def _load_actions() -> dict[str, dict]:
    global _actions
    if _actions is None:
        prof = load_robot_profile()
        raw = yaml.safe_load(prof.actions.catalog_path.read_text("utf-8"))
        entries = raw if isinstance(raw, list) else raw.get("actions", [])
        out = {}
        for spec in entries:
            if isinstance(spec, dict) and "name" in spec:
                out[spec["name"]] = spec
        _actions = out
        log.info(f"加载 {len(out)} 个动作")
    return _actions


def build_action_list_for_prompt() -> str:
    return "\n".join(f"- {n}: {s.get('description','')}" for n, s in _load_actions().items())


def action_triggers() -> dict[str, str]:
    return {n: s.get("triggers", "") for n, s in _load_actions().items()}


def is_ambient_action(name: str) -> bool:
    return bool(_load_actions().get(name, {}).get("is_ambient", False))


def available_action_names() -> set[str]:
    return set(_load_actions().keys())


async def execute_action_async(name: str, *, wait: bool = True) -> None:
    """请求 lease -> 切 mode -> adapter 播放 -> 释放 lease。"""
    spec = _load_actions().get(name)
    if spec is None:
        log.warn(f"动作库里没有 '{name}'，跳过")
        return
    ambient = bool(spec.get("is_ambient"))
    lease = request_interaction_action_lease(name)
    if not lease.granted:
        log.info(f"动作让位: {lease.reason}")
        return
    try:
        set_mode(RobotMode.AMBIENT_TALK if ambient else RobotMode.GESTURE)
        rag_name = spec.get("rag_name")
        if not rag_name:
            log.info(f"动作 '{name}' 没配 rag_name，只 log 不播放")
        elif wait:
            await get_adapter().play_action(rag_name)
        else:
            # ambient（talk 这类"边说边比"长 loop）不阻塞：原实现动作与语音并行，
            # voice 结束时 cancel 掉动作。这里起后台 task 并立即返回。
            task = asyncio.ensure_future(get_adapter().play_action(rag_name))
            await asyncio.sleep(0.05)
            if not task.done():
                task.cancel()
                log.info(f"动作 '{name}' 后台播放（ambient，voice 结束即 cancel）")
    except asyncio.CancelledError:
        log.info(f"动作 '{name}' 被取消")
        raise
    except Exception as e:
        log.warn(f"动作执行异常: {e}")
    finally:
        release_lease(lease.lease.id if lease.lease else None)
        set_mode(RobotMode.IDLE)

"""ReAct 工具循环 — 还原自 src/agents/interaction/llm_loop.py。

流式取 LLM 输出喂 TaggedStreamParser（REPLY 边出边送 TTS），
若模型发起 tool call 则执行并回喂，最多 MAX_REACT_ITERATIONS 轮，
仍未给出 REPLY 时用 FORCED_FINAL_SYSTEM_HINT 强制终局直答。
"""
from __future__ import annotations

import json
import time

from src.llm_client import ChatClient, LLMError
from src.logger import get_logger
from src.voice.stream_parser import TaggedStreamParser

log = get_logger("LLM")

# 原文常量（LZSS 解压所得）
MAX_REACT_ITERATIONS = 4
ACTIVATE_SKILL_TOOL = "activate_skill"
VISION_IMAGE_TOOL = "get_latest_vision_image"
SILENT_AFTER_TOOL_CALLS = {"cancel_navigation"}
FORCED_FINAL_SYSTEM_HINT = (
    "你已经调用过足够的工具，禁止再调用任何工具。现在必须基于以上工具结果和对话内容，"
    "直接生成给用户的最终答复。如果工具调用失败、没有结果、现有信息不足以支持确定答案，"
    "或不同来源互相冲突，必须如实说明暂时没有查到或无法确认，禁止猜测、补全或编造结论。"
    "输出格式：<ACTION>动作名</ACTION><REPLY>回复内容</REPLY>，回复要简短口语化，"
    "只回应用户本轮的输入，不要罗列所有工具结果。"
)


def run_llm_with_tools(client: ChatClient, messages: list[dict], parser: TaggedStreamParser,
                       tools: list[dict] | None = None, tool_impls: dict | None = None) -> dict:
    tool_impls = tool_impls or {}
    t0 = time.monotonic()
    first_chunk_ms = None
    tool_events: list[dict] = []
    msgs = list(messages)
    iterations_used = 0
    saw_reply = False

    for iteration in range(MAX_REACT_ITERATIONS):
        iterations_used = iteration + 1
        acc_content = ""
        acc_tool_calls: dict[int, dict] = {}
        try:
            for chunk in client.stream(msgs, tools=tools):
                if first_chunk_ms is None:
                    first_chunk_ms = (time.monotonic() - t0) * 1000
                if "content" in chunk:
                    acc_content += chunk["content"]
                    parser.feed(chunk["content"])
                if "tool_calls" in chunk:
                    for tc in chunk["tool_calls"]:
                        idx = tc.get("index", 0)
                        slot = acc_tool_calls.setdefault(idx, {"id": "", "name": "", "args": ""})
                        if tc.get("id"):
                            slot["id"] = tc["id"]
                        fn = tc.get("function") or {}
                        if fn.get("name"):
                            slot["name"] = fn["name"]
                        if fn.get("arguments"):
                            slot["args"] += fn["arguments"]
        except LLMError as e:
            log.error(f"ReAct 循环异常: {e}")
            break

        if "REPLY" in parser.values():
            saw_reply = True

        calls = [c for c in acc_tool_calls.values() if c["name"]]
        if not calls:
            break

        log.info(f"🔧 [iter {iteration}] LLM 决定调 {len(calls)} 个 tool: "
                 f"{[c['name'] for c in calls]}")
        msgs.append({"role": "assistant", "content": acc_content or "",
                     "tool_calls": [{"id": c["id"] or f"call_{i}", "type": "function",
                                     "function": {"name": c["name"], "arguments": c["args"] or "{}"}}
                                    for i, c in enumerate(calls)]})
        for i, c in enumerate(calls):
            impl = tool_impls.get(c["name"])
            try:
                args = json.loads(c["args"] or "{}")
            except json.JSONDecodeError:
                args = {}
            if impl is None:
                result = f"未知工具 '{c['name']}'"
            else:
                try:
                    result = str(impl(**args))
                except Exception as e:
                    result = f"执行失败: {e}"
            tool_events.append({"name": c["name"], "args": args, "result": result})
            log.info(f"   ↳ {c['name']}({args}) -> {result[:60]}")
            msgs.append({"role": "tool", "tool_call_id": c["id"] or f"call_{i}", "content": result})

    # 强制终局直答
    forced_final = False
    if not saw_reply and "REPLY" not in parser.values() and parser.full_stream().strip():
        # 模型给了纯文本但没按 <REPLY> 格式闭合：直接采用，不重新生成
        parser.finalize()
        saw_reply = "REPLY" in parser.values() or bool(parser.full_stream().strip())
    if not saw_reply and "REPLY" not in parser.values():
        forced_final = True
        log.info(f"ReAct 跑完 {iterations_used} 轮，强制结束。发起强制无工具终局直答。")
        msgs.append({"role": "system", "content": FORCED_FINAL_SYSTEM_HINT})
        try:
            for chunk in client.stream(msgs, tools=None):
                if "content" in chunk:
                    parser.feed(chunk["content"])
        except LLMError as e:
            log.warn(f"强制终局直答失败，维持空 REPLY 兜底: {e}")

    parser.finalize()
    return {
        "first_chunk_ms": first_chunk_ms,
        "total_ms": (time.monotonic() - t0) * 1000,
        "iterations_used": iterations_used,
        "forced_final": forced_final,
        "tool_events": tool_events,
    }

"""OpenAI 兼容 LLM 客户端（标准库实现，零第三方依赖）。

原实现用 langchain_openai.ChatOpenAI；这里用 urllib 直连
/chat/completions，支持流式与 function calling，行为等价。
"""
from __future__ import annotations

import json
import urllib.error
import urllib.request
from typing import Any, Iterator

from src.config import get_llm_provider
from src.logger import get_logger

log = get_logger("LLM")


class LLMError(RuntimeError):
    pass


class ChatClient:
    def __init__(self, provider: str, model: str, temperature: float = 0.0,
                 extra_body: dict | None = None, timeout: float = 60.0):
        p = get_llm_provider(provider)
        self.base_url = (p.base_url or "").rstrip("/")
        self.api_key = p.api_key
        self.model = model
        self.temperature = temperature
        self.extra_body = {**(p.extra_body or {}), **(extra_body or {})}
        self.timeout = timeout

    def _post(self, payload: dict, stream: bool):
        url = f"{self.base_url}/chat/completions"
        data = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        req = urllib.request.Request(url, data=data, method="POST")
        req.add_header("Content-Type", "application/json")
        req.add_header("Authorization", f"Bearer {self.api_key}")
        if stream:
            req.add_header("Accept", "text/event-stream")
        try:
            return urllib.request.urlopen(req, timeout=self.timeout)
        except urllib.error.HTTPError as e:
            raise LLMError(f"HTTP {e.code}: {e.read().decode('utf-8', 'replace')[:300]}") from e
        except Exception as e:
            raise LLMError(str(e)) from e

    def stream(self, messages: list[dict], tools: list[dict] | None = None) -> Iterator[dict]:
        """逐块产出 {'content': str} 或 {'tool_calls': [...]}"""
        payload: dict[str, Any] = {
            "model": self.model,
            "messages": messages,
            "temperature": self.temperature,
            "stream": True,
            **self.extra_body,
        }
        if tools:
            payload["tools"] = tools
        resp = self._post(payload, stream=True)
        for raw in resp:
            line = raw.decode("utf-8", "replace").strip()
            if not line.startswith("data:"):
                continue
            body = line[5:].strip()
            if body == "[DONE]":
                break
            try:
                obj = json.loads(body)
            except json.JSONDecodeError:
                continue
            for ch in obj.get("choices", []):
                delta = ch.get("delta") or {}
                if delta.get("content"):
                    yield {"content": delta["content"]}
                if delta.get("tool_calls"):
                    yield {"tool_calls": delta["tool_calls"]}

    def invoke(self, messages: list[dict], tools: list[dict] | None = None) -> dict:
        payload: dict[str, Any] = {
            "model": self.model,
            "messages": messages,
            "temperature": self.temperature,
            **self.extra_body,
        }
        if tools:
            payload["tools"] = tools
        resp = self._post(payload, stream=False)
        obj = json.loads(resp.read().decode("utf-8", "replace"))
        return obj["choices"][0]["message"]

"""TaggedStreamParser — 还原自 src/voice/stream_parser.py。

边流边解析 <TAG>value</TAG>：
  - stream_tag（如 REPLY）的内容按句子边界增量 emit，让 TTS 能早开口
  - 其余 tag（如 ACTION / AGENT）在闭合时整体 emit
常量与边界字符取自 LZSS 解压出的原文。
"""

from __future__ import annotations

from collections.abc import Callable

# 原文常量
SENTENCE_BOUNDARIES = "。！？.!?；;~～，,、"
STRONG_SENTENCE_BOUNDARIES = "。！？.!?；;~～"
MIN_WEAK_BOUNDARY_CHARS = 8


class TaggedStreamParser:
    def __init__(self, tags: list[str], stream_tag: str):
        if stream_tag not in tags:
            raise ValueError(f"stream_tag '{stream_tag}' 必须在 tags 列表里")
        self.tags = list(tags)
        self.stream_tag = stream_tag

        self._buf = ""
        self._state = "idle"  # idle | normal | stream
        self._cur: str | None = None
        self._normal_buf = ""
        self._pending = ""  # stream 尚未 flush 的尾巴
        self._stream_full = ""
        self._full = ""
        self._values: dict[str, str] = {}
        self._defaults: dict[str, str] = {}
        self._stream_done_emitted = False

        # 回调
        self.on_tag_value: Callable[[str, str], None] | None = None
        self.on_stream_chunk: Callable[[str], None] | None = None
        self.on_stream_done: Callable[[str], None] | None = None

    # ---------- public ----------
    def default_for_tag(
        self, tag_name: str, default_value: str
    ) -> TaggedStreamParser:
        self._defaults[tag_name] = default_value
        return self

    def feed(self, text: str) -> None:
        if not text:
            return
        self._full += text
        self._buf += text
        self._process()

    def finalize(self) -> None:
        # 流结束：把还没闭合的 stream tag 收尾
        if self._state == "stream":
            self._append_stream(self._buf)
            self._buf = ""
            self._flush(force=True)
            self._emit_tag(self.stream_tag, self._stream_full.strip())
            self._emit_stream_done()
        elif self._state == "normal" and self._cur:
            self._normal_buf += self._buf
            self._buf = ""
            self._emit_tag(self._cur, self._normal_buf.strip())
        self._state, self._cur = "idle", None
        # 没出现过的 tag 用默认值补
        for tag, dv in self._defaults.items():
            if tag not in self._values:
                self._emit_tag(tag, dv)
        self._emit_stream_done()

    def full_stream(self) -> str:
        return self._full

    def values(self) -> dict[str, str]:
        return dict(self._values)

    # ---------- state machine ----------
    def _process(self) -> None:
        progress = True
        while progress:
            progress = False
            if self._state == "idle":
                best = None
                for t in self.tags:
                    i = self._buf.find(f"<{t}>")
                    if i >= 0 and (best is None or i < best[1]):
                        best = (t, i)
                if best:
                    tag, i = best
                    self._buf = self._buf[i + len(tag) + 2 :]
                    self._cur = tag
                    if tag == self.stream_tag:
                        self._state = "stream"
                        self._pending = ""
                        self._stream_full = ""
                        self._stream_done_emitted = False
                    else:
                        self._state = "normal"
                        self._normal_buf = ""
                    progress = True
                else:
                    keep = self._partial_tail_len()
                    if keep < len(self._buf):
                        self._buf = self._buf[len(self._buf) - keep :] if keep else ""

            elif self._state == "normal":
                close = f"</{self._cur}>"
                i = self._buf.find(close)
                if i >= 0:
                    self._normal_buf += self._buf[:i]
                    self._buf = self._buf[i + len(close) :]
                    self._emit_tag(self._cur, self._normal_buf.strip())
                    self._state, self._cur = "idle", None
                    progress = True
                else:
                    keep = self._partial_tail_len()
                    take = len(self._buf) - keep
                    if take > 0:
                        self._normal_buf += self._buf[:take]
                        self._buf = self._buf[take:]

            elif self._state == "stream":
                close = f"</{self._cur}>"
                i = self._buf.find(close)
                if i >= 0:
                    self._append_stream(self._buf[:i])
                    self._buf = self._buf[i + len(close) :]
                    self._flush(force=True)
                    self._emit_tag(self._cur, self._stream_full.strip())
                    self._emit_stream_done()
                    self._state, self._cur = "idle", None
                    progress = True
                else:
                    keep = self._partial_tail_len()
                    take = len(self._buf) - keep
                    if take > 0:
                        self._append_stream(self._buf[:take])
                        self._buf = self._buf[take:]

    def _partial_tail_len(self) -> int:
        """buffer 尾部可能是被切断的标签（'<REP'），保留它等下一个 chunk。"""
        idx = self._buf.rfind("<")
        if idx == -1:
            return 0
        if ">" in self._buf[idx:]:
            return 0
        return len(self._buf) - idx

    # ---------- stream text ----------
    def _append_stream(self, text: str) -> None:
        if not text:
            return
        self._pending += text
        self._stream_full += text
        self._flush(force=False)

    def _flush(self, force: bool) -> None:
        if not self._pending:
            return
        if force:
            self._emit_stream_chunk(self._pending)
            self._pending = ""
            return
        idx = self._last_boundary_index(self._pending)
        if idx >= 0:
            self._emit_stream_chunk(self._pending[: idx + 1])
            self._pending = self._pending[idx + 1 :]

    @staticmethod
    def _last_boundary_index(pending: str) -> int:
        for i in range(len(pending) - 1, -1, -1):
            c = pending[i]
            if c in STRONG_SENTENCE_BOUNDARIES:
                return i
            if c in SENTENCE_BOUNDARIES and (i + 1) >= MIN_WEAK_BOUNDARY_CHARS:
                return i
        return -1

    # ---------- emit ----------
    def _emit_tag(self, tag_name: str, value: str) -> None:
        self._values[tag_name] = value
        if self.on_tag_value:
            self.on_tag_value(tag_name, value)

    def _emit_stream_chunk(self, text: str) -> None:
        if text and self.on_stream_chunk:
            self.on_stream_chunk(text)

    def _emit_stream_done(self) -> None:
        if self._stream_done_emitted:
            return
        self._stream_done_emitted = True
        if self.on_stream_done:
            self.on_stream_done(self._stream_full.strip())

"""配置加载 — 还原自 src/config.py（Cython 编译模块）。

settings.yaml + settings_editable.yaml 深度合并（editable 覆盖 base），
与原实现一致（settings.yaml 头部注释明确写了这个合并行为）。
"""
from __future__ import annotations

import os
from pathlib import Path
from typing import Any

import yaml

_CONFIG: dict[str, Any] | None = None
_ROOT = Path(__file__).resolve().parent.parent


def project_root() -> Path:
    return _ROOT


def _deep_merge(base: dict, override: dict) -> dict:
    out = dict(base)
    for k, v in (override or {}).items():
        if isinstance(v, dict) and isinstance(out.get(k), dict):
            out[k] = _deep_merge(out[k], v)
        else:
            out[k] = v
    return out


def get_config() -> dict[str, Any]:
    global _CONFIG
    if _CONFIG is None:
        base = yaml.safe_load((_ROOT / "config" / "settings.yaml").read_text("utf-8")) or {}
        ed_path = _ROOT / "config" / "settings_editable.yaml"
        editable = {}
        if ed_path.exists():
            editable = yaml.safe_load(ed_path.read_text("utf-8")) or {}
        _CONFIG = _deep_merge(base, editable)
    return _CONFIG


def reset_config() -> None:
    global _CONFIG
    _CONFIG = None


class Provider:
    """LLM provider：base_url + api_key（+ extra_body）。"""

    def __init__(self, name: str, base_url: str, api_key: str, extra_body: dict | None = None):
        self.name = name
        self.base_url = base_url
        self.api_key = api_key
        self.extra_body = extra_body or {}


def _read_local_dashscope_key() -> str:
    p = Path.home() / ".config" / "dashscope" / "api_key"
    if p.exists():
        return p.read_text().strip()
    return ""


def get_llm_provider(name: str = "qwen") -> Provider:
    """还原 provider 解析；允许用环境变量覆盖 base_url/key 以便脱离专属网关运行。

    原配置里的 base_url 是该账号的百炼专属 endpoint；本地复现时用
    GALBOT_LLM_BASE_URL 覆盖成公共 compatible-mode endpoint 即可。
    """
    cfg = get_config().get("llm", {}).get("providers", {}).get(name, {}) or {}
    base_url = os.environ.get("GALBOT_LLM_BASE_URL") or cfg.get("base_url", "")
    key_env = cfg.get("api_key_env", "DASHSCOPE_API_KEY")
    api_key = os.environ.get(key_env) or os.environ.get("DASHSCOPE_API_KEY") or _read_local_dashscope_key()
    return Provider(name, base_url, api_key, cfg.get("extra_body"))

