"""VoiceOutput — 还原自 src/voice/voice_output.py（本地复现用打印代替真 TTS 播放）。

session 语义、abort/打断、recent_tts 回声窗口与原实现一致。
"""
from __future__ import annotations

import time

from src.logger import get_logger

log = get_logger("Voice")


class VoiceOutput:
    def __init__(self) -> None:
        self._session_id = 0
        self._recent: list[tuple[float, str]] = []
        self._playing = False

    def current_session_id(self) -> int:
        return self._session_id

    def is_session_interrupted(self, session_id: int | None) -> bool:
        return session_id is not None and session_id != self._session_id

    def feed_text(self, text: str, session_id: int | None = None) -> None:
        sid = self._session_id if session_id is None else session_id
        if self.is_session_interrupted(sid):
            return
        self._playing = True
        self._recent.append((time.monotonic(), text))
        print(f"   🔊 [TTS 播放] {text}")

    def get_recent_tts_text(self, window_seconds: float = 5.0) -> str:
        now = time.monotonic()
        return "".join(t for ts, t in self._recent if now - ts <= window_seconds)

    def abort(self, expected_session: int | None = None) -> None:
        if expected_session is None or expected_session == self._session_id:
            self._session_id += 1
            self._playing = False
            log.info("abort: 旧语音已打断")

    def is_speaking(self) -> bool:
        return self._playing


_vo = VoiceOutput()


def get_voice_output() -> VoiceOutput:
    return _vo

"""统一日志工具 — 通过环境变量 LOG_LEVEL 控制详细程度。

用法:
    from src.logger import get_logger
    log = get_logger("TTS")          # 组件名，作为日志前缀

    log.info("HTTP 200 OK")          # 默认会打印
    log.debug("POST URL: ...")       # 只在 LOG_LEVEL=debug 时打印
    log.warn("retry...")             # warn 及以上一直打印
    log.error("auth failed")         # error 一直打印

环境变量:
    LOG_LEVEL=debug  — 全部日志（debug + info + warn + error）
    LOG_LEVEL=info   — 默认。只打 info / warn / error
    LOG_LEVEL=warn   — 只打 warn / error
    LOG_LEVEL=error  — 只打 error

约定:
    info  = 用户关心的关键事件（动作触发、播放开始、总耗时）
    debug = 开发者排错用的细节（HTTP headers、延迟分段、每段 chunk 数）
    warn  = 异常但不致命（重试、跳过）
    error = 致命错误（请求失败、配置错误）
"""
import os
import sys
from datetime import datetime


_LEVELS = {"debug": 10, "info": 20, "warn": 30, "error": 40}
_CURRENT_LEVEL = _LEVELS.get(os.getenv("LOG_LEVEL", "info").lower(), 20)
_FILE_SINK_DISABLED = False
_APP_LOG_ENV = "GALBOT_RUNTIME_APP_LOG"


def _runtime_app_log_enabled() -> bool:
    return os.getenv(_APP_LOG_ENV, "").strip().lower() in {"1", "true", "yes", "on"}


def _append_runtime_app_log(line: str) -> None:
    global _FILE_SINK_DISABLED
    if _FILE_SINK_DISABLED or not _runtime_app_log_enabled():
        return
    try:
        from src.runtime import runtime_logger

        if not runtime_logger.app_log_enabled():
            return
        path = runtime_logger.app_log_path()
        from src.runtime import io_worker

        io_worker.append_text(path, f"{line}\n", priority=90)
    except Exception:
        # Logging must never break robot runtime behavior. If this environment
        # cannot create the sink, stop retrying to avoid repeated hot-path cost.
        _FILE_SINK_DISABLED = True


def _emit(level_value: int, prefix: str, msg: str) -> None:
    if level_value >= _CURRENT_LEVEL:
        level_name = {10: "DEBUG", 20: "INFO", 30: "WARNING", 40: "ERROR"}[level_value]
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S,%f")[:-3]
        line = f"{timestamp} [{level_name}] [{prefix}] {msg}"
        # error 走 stderr，其余走 stdout — 方便管道过滤
        stream = sys.stderr if level_value >= 40 else sys.stdout
        print(line, file=stream, flush=True)
        _append_runtime_app_log(line)


class _Logger:
    __slots__ = ("component",)

    def __init__(self, component: str):
        self.component = component

    def debug(self, msg: str) -> None:
        _emit(10, self.component, msg)

    def info(self, msg: str) -> None:
        _emit(20, self.component, msg)

    def warn(self, msg: str) -> None:
        _emit(30, self.component, f"⚠️ {msg}")

    def error(self, msg: str) -> None:
        _emit(40, self.component, f"❌ {msg}")


def get_logger(component: str) -> _Logger:
    return _Logger(component)


def current_level() -> str:
    """返回当前生效的日志级别字符串。"""
    inv = {v: k for k, v in _LEVELS.items()}
    return inv.get(_CURRENT_LEVEL, "info")

"""Skill 加载 —— 扫真 SKILL.md 的 frontmatter（AES 解密原文）。

对应原实现 src/skills/loader.py：按 frontmatter 的 name/description/metadata
注册 skill，供 load_skill / activate_skill 两个 meta tool 使用。
"""
from __future__ import annotations

from pathlib import Path

import yaml

from src.config import get_config
from src.logger import get_logger

log = get_logger("Skill")
_DIR = Path(__file__).resolve().parent
_skills: dict[str, dict] | None = None


def _parse_frontmatter(text: str) -> tuple[dict, str]:
    if not text.startswith("---"):
        return {}, text
    end = text.find("\n---", 3)
    if end == -1:
        return {}, text
    fm = yaml.safe_load(text[3:end]) or {}
    return fm, text[end + 4:]


def load_all() -> dict[str, dict]:
    global _skills
    if _skills is not None:
        return _skills
    disabled = set(get_config().get("agents", {}).get("interaction", {}).get("disabled_skills", []) or [])
    out: dict[str, dict] = {}
    for md in sorted(_DIR.glob("*/SKILL.md")):
        name = md.parent.name
        text = md.read_text("utf-8")
        fm, body = _parse_frontmatter(text)
        if name in disabled or fm.get("name") in disabled:
            log.info(f"skill '{name}' 已通过 settings.yaml disabled_skills 禁用")
            continue
        out[fm.get("name", name)] = {
            "name": fm.get("name", name),
            "description": fm.get("description", ""),
            "metadata": fm.get("metadata", {}),
            "body": body.strip(),
            "path": str(md),
        }
    _skills = out
    log.info(f"扫到 {len(out)} 个 skill (frontmatter-only): {sorted(out)}")
    return out


def skill_catalog() -> str:
    return "\n".join(f"- {s['name']}: {s['description']}" for s in load_all().values())


def load_skill(name: str) -> str:
    """把 skill 的完整指令正文喂回 LLM 上下文（原实现同语义）。"""
    s = load_all().get(name)
    if not s:
        return f"没有 skill '{name}'。可用：{'、'.join(load_all())}"
    log.info(f"📚 LLM 加载 skill: {name}")
    return s["body"][:6000]

