def get_galbot_info(topic: str = "general") -> str:
    """还原自 src/skills/company_info/tools/company_info.py。

    签名 default='general' 与原骨架一致：解析 topic（精确 key 或别名命中），
    未命中则兑底返回 general 的 content；返回的是干净正文，不是 yaml 全文。
    """
    info = _load("galbot_info") or {}
    topics = info.get("topics", {}) if isinstance(info, dict) else {}
    if not topics:
        return "暂无公司资料。"
    t = (topic or "general").strip()
    resolved = None
    for key, val in topics.items():
        if not isinstance(val, dict):
            continue
        if t == key or t in (val.get("aliases") or []):
            resolved = key
            break
        # 别名/主题的宽松包含（原实现同样支持别名/部分匹配）
        if t in key or any(t in str(a) for a in (val.get("aliases") or [])):
            resolved = key
            break
    if resolved is None:
        resolved = "general" if "general" in topics else next(iter(topics))
    content = topics[resolved].get("content", "") if isinstance(topics[resolved], dict) else str(topics[resolved])
    return (content or "").strip() or "暂无公司资料。"

