#!/usr/bin/env python3
"""函数名 -> 机器码地址映射（stripped Cython aarch64 .so）。

原理（无符号表）：
  Cython 把模块级 def 函数放进 static PyMethodDef 表 __pyx_methods[]，条目结构
  {char* ml_name; PyCFunction ml_meth; int ml_flags; char* ml_doc}（aarch64 32B）。
  该表在 .data 里，函数指针/字符串指针都依赖 R_AARCH64_RELATIVE 重定位，
  .so 加载前磁盘上内容是 0，但 .rela.dyn 里 r_offset=字段位置、r_addend=目标地址。
  于是：在 .rodata 里找到函数名字符串地址 S；在 .rela.dyn 里找 addend==S 的重定位，
  其 offset 即 ml_name 字段位置；offset+8 处的重定位 addend 即 __pyx_pw wrapper 地址。
用法: python3 map_funcs.py <so> [函数名...]
"""
import sys
from elftools.elf.elffile import ELFFile

def load(elf):
    rela = {}
    for sec in elf.iter_sections():
        if sec['sh_type'] == 'SHT_RELA':
            for r in sec.iter_relocations():
                rela[r['r_offset']] = (r['r_info_type'], r['r_addend'])
    return rela

def strings_of(elf):
    """rodata 里的 C 字符串 -> (addr, 内容)"""
    out = []
    for sec in elf.iter_sections():
        if sec.name != '.rodata':
            continue
        data = sec.data()
        base = sec['sh_addr']
        i = 0
        n = len(data)
        while i < n:
            j = data.find(b'\x00', i)
            if j < 0:
                j = n
            blob = data[i:j]
            if 3 <= len(blob) <= 120:
                out.append((base + i, blob))
            i = j + 1
    return out

def map_functions(so_path, names):
    with open(so_path, 'rb') as f:
        elf = ELFFile(f)
        rela = load(elf)
        # 反向: addend -> list of offsets
        addend_to_offsets = {}
        for off, (typ, addend) in rela.items():
            addend_to_offsets.setdefault(addend, []).append(off)
        strs = strings_of(elf)
        name_addr = {s.decode('utf-8', 'replace'): a for a, s in strs}
        result = {}
        for name in names:
            sa = name_addr.get(name)
            if sa is None:
                result[name] = None
                continue
            offs = addend_to_offsets.get(sa, [])
            found = None
            for off in offs:
                # ml_meth 在 ml_name 之后 8 字节
                meth = addend_to_offsets.get(off + 8, [])
                if meth:
                    found = (off, sa, off + 8, meth[0])
                    break
            result[name] = found
        return result, name_addr

if __name__ == '__main__':
    so = sys.argv[1]
    names = sys.argv[2:]
    res, _ = map_functions(so, names)
    for n, v in res.items():
        if v is None:
            print(f'{n}: NOT FOUND')
        else:
            off, saddr, moff, waddr = v
            print(f'{n}: ml_name@{hex(off)} str@{hex(saddr)} wrapper@{hex(waddr)}')
