    text = elf.get_section_by_name('.text')
    ro = elf.get_section_by_name('.rodata')
    return elf, text['sh_addr'], text.data(), ro['sh_addr'], ro.data()

def ro_strings(robase, rodata):
    out = {}
    i = 0
    while i < len(rodata):
        j = rodata.find(b'\x00', i)
        if j < 0: j = len(rodata)
        b = rodata[i:j]
        if 3 <= len(b) <= 200 and min(b) >= 32:
            out[robase + i] = b.decode('utf-8', 'replace')
        i = j + 1
    return out

def strings_referenced(so, func_start, func_end):
