    md = Cs(CS_ARCH_ARM64, CS_MODE_ARM)
    md.detail = True
    regs = {}
    hits = []
    for i in md.disasm(tdata[func_start - tbase: func_end - tbase], func_start):
        # adrp: 计算页基址
        if i.mnemonic == 'adrp':
            rd = i.operands[0].reg; imm = i.operands[1].imm
            regs[rd] = (i.address & ~0xfff) + (imm << 12)
