"""解析 .text 里引用的 .rodata 字符串（adrp/add 追踪 + 内存基址），用于识别函数身份/还原字符串引用。"""
from elftools.elf.elffile import ELFFile
from capstone import Cs, CS_ARCH_ARM64, CS_MODE_ARM

def _load(so):
    f = open(so, 'rb'); elf = ELFFile(f)
    text = elf.get_section_by_name('.text')
    ro = elf.get_section_by_name('.rodata')
    return elf, text['sh_addr'], text.data(), ro['sh_addr'], ro.data()

def ro_strings(robase, rodata):
    out = {}
    i = 0
    while i < len(rodata):
        j = rodata.find(b'\x00', i)
        if j < 0: j = len(rodata)
        b = rodata[i:j]
        if 3 <= len(b) <= 200 and min(b) >= 32:
            out[robase + i] = b.decode('utf-8', 'replace')
        i = j + 1
    return out

def strings_referenced(so, func_start, func_end):
    elf, tbase, tdata, robase, rodata = _load(so)
    strs = ro_strings(robase, rodata)
    md = Cs(CS_ARCH_ARM64, CS_MODE_ARM); md.detail = True
    regs = {}
    hits = []
    for i in md.disasm(tdata[func_start - tbase: func_end - tbase], func_start):
        if i.mnemonic == 'adrp' and len(i.operands) == 2:
            rd = i.operands[0].reg; imm = i.operands[1].imm
            regs[rd] = (i.address & ~0xfff) + (imm << 12)
        elif i.mnemonic == 'add' and len(i.operands) == 3:
            rd = i.operands[0].reg
            if i.operands[1].type == 1 and i.operands[2].type == 3 and i.operands[1].reg in regs:
                regs[rd] = regs[i.operands[1].reg] + i.operands[2].imm
        # 检查该指令所有操作数（含内存基址寄存器）是否命中已知字符串地址
        for op in i.operands:
            r = None
            if op.type == 1:      # 寄存器
                r = op.reg
            elif op.type == 3:    # 内存: base+disp
                r = op.mem.base
            if r is not None and r in regs and regs[r] in strs:
                hits.append((i.address, strs[regs[r]], regs[r], i.mnemonic, i.op_str))
        # 指令会写回目标寄存器，地址被覆盖后失效
        if i.mnemonic in ('adrp','add') or (len(i.operands) and i.operands[0].type == 1):
            pass  # regs 已在上方按需更新；不主动清除，保持近似
    # 去重
    seen = set(); out = []
    for h in hits:
        k = (h[0], h[1])
        if k not in seen:
            seen.add(k); out.append(h)
    return out

if __name__ == '__main__':
    import sys
    so = sys.argv[1]; s, e = int(sys.argv[2],16), int(sys.argv[3],16)
    for pc, sstr, addr, mn, ops in strings_referenced(so, s, e):
        print(f'{pc:#x}  ref {addr:#x}  "{sstr[:90]}"   [{mn} {ops}]')
