"""构建 .so 的指针解析表：data 地址 -> 目标(.rodata 字符串 / .text 函数 / GOT 槽)。"""
from elftools.elf.elffile import ELFFile

def build(so):
    f = open(so, 'rb'); elf = ELFFile(f)
    sec = {}
    for s in elf.iter_sections():
        sec[s.name] = s
    ro = sec['.rodata']; robase, rodata = ro['sh_addr'], ro.data()
    text = sec['.text']; tbase, tsize = text['sh_addr'], text['sh_size']
    # 字符串表
    strings = {}
    i = 0
    while i < len(rodata):
        j = rodata.find(b'\x00', i)
        if j < 0: j = len(rodata)
        b = rodata[i:j]
        if 3 <= len(b) <= 200 and min(b) >= 32:
            strings[robase + i] = b.decode('utf-8', 'replace')
        i = j + 1
    # 重定位: data 字段地址 -> 目标地址 (R_AARCH64_RELATIVE = 1027)
    ptr = {}   # data_addr -> target
    for r in sec['.rela.dyn'].iter_relocations():
        if r['r_info_type'] == 1027:
            ptr[r['r_offset']] = r['r_addend']
    B = lambda a: ('str', strings[a]) if a in strings else \
                  ('func',) if tbase <= a < tbase + tsize else \
                  ('data',) 
    return elf, strings, ptr, (tbase, tsize), (robase, len(rodata))
