#!/usr/bin/env python3
"""字符串/函数引用标注：追踪 adrp(+add 或 +ldr) → data/GOT 槽 → (reloc) → .rodata 字符串 或 .text 函数。"""
from elftools.elf.elffile import ELFFile
from capstone import Cs, CS_ARCH_ARM64, CS_MODE_ARM
from resolve import build

def annotate(so, func_start, func_end):
    elf, strings, ptr, (tbase, tsize), _ = build(so)
    md = Cs(CS_ARCH_ARM64, CS_MODE_ARM); md.detail = True
    text = elf.get_section_by_name('.text')
    code = text.data()
    regs = {}
    lines = []
    for i in md.disasm(code[func_start - tbase: func_end - tbase], func_start):
        note = ''
        # 解析本指令用到的数据地址
        if i.mnemonic == 'adrp' and len(i.operands) == 2:
            rd = i.operands[0].reg; imm = i.operands[1].imm
            regs[rd] = ('page', (i.address & ~0xfff) + (imm << 12))
        elif i.mnemonic == 'add' and len(i.operands) == 3:
            rd = i.operands[0].reg
            if i.operands[1].type == 1 and i.operands[2].type == 3 and i.operands[1].reg in regs and regs[i.operands[1].reg][0] == 'page':
                regs[rd] = ('addr', regs[i.operands[1].reg][1] + i.operands[2].imm)
        elif i.mnemonic == 'ldr' and len(i.operands) == 2:
            # ldr xN, [xM, #off] 且 xM 是 page → 这是从 GOT 槽取指针
            dst = i.operands[0].reg
            if i.operands[1].type == 3 and i.operands[1].mem.base in regs and regs[i.operands[1].mem.base][0] == 'page':
                slot = regs[i.operands[1].mem.base][1] + i.operands[1].mem.disp
                if slot in ptr:
                    t = ptr[slot]
                    regs[dst] = ('target', t)
                    if t in strings:
                        note = f'  ; GOT-> "{strings[t][:60]}"'
                    elif tbase <= t < tbase + tsize:
                        note = f'  ; GOT-> func {t:#x}'
        # 本指令操作数引用了已知字符串地址（直接 addr 或经 GOT）
        for op in i.operands:
            r = op.reg if op.type == 1 else (op.mem.base if op.type == 3 else None)
            if r in regs and regs[r][0] == 'target':
                t = regs[r][1]
                if t in strings:
                    note = f'  ; "{strings[t][:60]}"'
                elif tbase <= t < tbase + tsize:
                    note = f'  ; func {t:#x}'
        lines.append((i.address, i.mnemonic, i.op_str, note))
    return lines

if __name__ == '__main__':
    import sys
    so = sys.argv[1]; s, e = int(sys.argv[2],16), int(sys.argv[3],16)
    for addr, mn, ops, note in annotate(so, s, e):
        if note:
            print(f'{addr:#x}: {mn:<8} {ops}{note}')
